definition.script:
pipeline {
  agent any

  stages {
    stage('🔍 Watch Pipeline') {
      steps {
        script {
          def jobName   = 'pfe-devsecops-pipeline'
          def stateFile = 'watcher_state.json'

          // ── Récupère le dernier build ──
          def response = httpRequest(
            url                : "http://jenkins:8080/job/${jobName}/lastBuild/api/json",
            httpMode           : 'GET',
            validResponseCodes : '100:599',
            ignoreSslErrors    : true
          )

          if (response.status == 404 || !response.content.trim().startsWith('{')) {
            echo "⚠️ Job introuvable"
            return
          }

          def buildInfo  = parseBuild(response.content)
          def isBuilding = buildInfo[0] as Boolean
          def result     = buildInfo[1] as String
          def number     = buildInfo[3] as Integer
          def elapsed    = (System.currentTimeMillis() - (buildInfo[2] as Long)) / 1000 / 60

          // ── Charge le dernier numéro stocké ──
          def lastNumber = 0
          if (fileExists(stateFile)) {
            def stateInfo = parseState(readFile(stateFile).trim())
            lastNumber    = stateInfo as Integer
          }

          echo "Build actuel : #${number} | Stocké : #${lastNumber} | Result: ${result} | Building: ${isBuilding}"

          // ══════════════════════════════
          // CONDITION UNIQUE
          // ══════════════════════════════

          // Numéro identique → rien à faire
          if (number == lastNumber) {
            echo "✅ Pas de nouveau build — rien à faire"
            return
          }

          // Nouveau build détecté → sauvegarde dans tous les cas
          writeFile file: stateFile, text: """{"lastBuildNumber":${number}}"""
          echo "💾 Nouveau build stocké : #${number}"

          // Nouveau build FAILURE → notifie n8n
          if (!isBuilding && result == 'FAILURE') {
            echo "❌ Build #${number} FAILURE — notification n8n"
            sendToN8n(jobName, number, elapsed, 'pipeline_failed')

          // Nouveau build BLOQUÉ
          } else if (isBuilding && elapsed > 15) {
            echo "🚨 Build #${number} BLOQUÉ — notification n8n"
            sendToN8n(jobName, number, elapsed, 'pipeline_blocked')

          // Nouveau build SUCCESS ou en cours
          } else {
            echo "✅ Build #${number} : ${result ?: 'EN COURS'} — rien à faire"
          }
        }
      }
    }
  }
}

@NonCPS
def parseBuild(String content) {
  def build = new groovy.json.JsonSlurper().parseText(content)
  return [
    build.building,
    build.result ?: 'IN_PROGRESS',
    build.timestamp as Long,
    build.number as Integer
  ]
}

@NonCPS
def parseState(String content) {
  def state = new groovy.json.JsonSlurper().parseText(content)
  return state.lastBuildNumber as Integer
}

def sendToN8n(jobName, number, elapsed, event) {
  def payload = """{
    "event": "${event}",
    "job": "${jobName}",
    "build_number": "${number}",
    "build_url": "http://jenkins:8080/job/${jobName}/${number}/",
    "logs_url": "http://jenkins:8080/job/${jobName}/${number}/consoleText",
    "elapsed_minutes": ${elapsed.toInteger()},
    "severity": "HIGH"
  }"""

  httpRequest(
    url                : 'http://172.31.172.61:5678/webhook/jenkins-event',
    httpMode           : 'POST',
    contentType        : 'APPLICATION_JSON',
    requestBody        : payload,
    customHeaders      : [[name: 'X-API-Key', value: 'devsecops-secret-2024']],
    ignoreSslErrors    : true,
    validResponseCodes : '100:599'
  )
  echo "✅ n8n notifié : ${event}"
}
